// Timeline — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, V1_INSTALL_AT_MS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Timeline app's origin (see `apps/registry/apps/timeline.ts`). */
    readonly VITE_TIMELINE_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/timeline` calls: its `ProxyMethod` table in
// `web/timeline/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Not granted, on purpose: the raw `timeline.moments` / `.moment` / `.trips` / `.traces` reads
// (the projected surface supersedes them), `timeline.movementRoute` (no leg boundaries — the maps
// read every leg in one `movementRoutes`), and of `mapRegion.*` only the map's two reads — no
// `mapRegion.regionsIn` / `.catalog`, which no Timeline map calls. Nothing of another app's: no
// `fs.*`, no `contact.*`, no `calendar.*`.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'timeline.feed',
  'timeline.feed.observe',
  'timeline.momentDetail',
  'timeline.trip',
  'timeline.places',
  'timeline.places.observe',
  'timeline.place',
  'timeline.renamePlace',
  'timeline.setPlaceRole',
  'timeline.mergePlaces',
  'timeline.unmergePlace',
  'timeline.acceptTripSuggestion',
  'timeline.dismissTripSuggestion',
  // The trip, movement and place maps (web-app-suite.md Wave 3, Timeline routes).
  'timeline.movementRoutes',
  'mapRegion.regionAt',
  'mapRegion.streamRange',
]

const PROD_ORIGIN = 'https://timeline.tenshu.app'

export const timeline: HostedApp = {
  id: 'timeline',
  order: 30,
  title: 'Timeline',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_TIMELINE_ORIGIN',
  devPort: 5177,
  origin: () => appOrigin(import.meta.env.VITE_TIMELINE_ORIGIN, PROD_ORIGIN, 5177),
  methods: METHODS,
  routePath: 'timeline/*',
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'timeline',
    label: 'Timeline',
    description: 'Where you have been, end-to-end encrypted.',
    version: '0.1.0',
    installedAtMs: V1_INSTALL_AT_MS,
    launchPath: '/timeline',
    // ⚠ The permissions listed here are DISPLAY data — what the app can actually call is `methods`.
    permissions: [
      {
        id: 'timeline.read',
        label: 'Read your timeline',
        description: 'See your visits, movements, trips and places.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'timeline.write',
        label: 'Edit your places and trips',
        description: 'Rename and label places, merge or separate them, and save suggested trips.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'timeline',
        label: 'TimelineService',
        reason: 'Stores your moments and trips, encrypted client-side.',
      },
      {
        id: 'place',
        label: 'PlaceService',
        reason: 'Stores your places, their names and labels.',
      },
      {
        id: 'health',
        label: 'HealthService',
        reason: 'Names the activity behind a workout moment. Read only.',
      },
    ],
  },
}

export default timeline
